-- Seed data ported from the Base44 NSS question bank (src/lib/questionBank.js).
-- 50 "would-you-rather" questions, each mapped to two of the seven need clusters.

insert into public.nss_questions
  (id, topic, cluster_a, cluster_b, standard_question, standard_option_a, standard_option_b,
   sharpened_question, sharpened_option_a, sharpened_option_b)
values
  (1, 'Saturday Morning', 'Stability', 'Agency', 'You wake up on a Saturday morning with no set plans.', 'You write down a few things you want to get done to give the day a clear shape.', 'You wait to see what you feel like doing before making any moves.', 'Which would ruin your mood more?', 'A last-minute change to a plan you liked.', 'Being stuck in a schedule you no longer feel like doing.'),
  (2, 'Furniture Assembly', 'Stability', 'Agency', 'You just bought a piece of furniture that requires assembly.', 'You read the instruction manual step-by-step from the beginning.', 'You start building it immediately to see if you can figure it out.', 'Which would feel more frustrating?', 'Making a mistake because you didn''t read the manual.', 'Wasting time reading when you could have just been doing.'),
  (3, 'Solo Road Trip', 'Connections', 'Ecosystem', 'You have a two-hour drive ahead of you by yourself.', 'You use the time to call someone and catch up.', 'You put on your favorite playlist and enjoy the time to yourself.', 'Which would make you more restless?', 'Too much silence for too long.', 'A constant stream of noise you can''t turn off.'),
  (4, 'Hotel Arrival', 'Stability', 'Agency', 'You arrive at a hotel for a vacation.', 'You unpack your bags to feel settled and organized.', 'You drop your bags and head out to explore the neighborhood.', 'Which would make you feel more uneasy?', 'Not having a comfortable home base to return to.', 'Committing to an itinerary instead of following your gut.'),
  (5, 'New Hobby', 'Stability', 'Agency', 'You are considering starting a new hobby.', 'You find an expert to make sure you learn the right way from day one.', 'You experiment on your own to see what you can discover by trial and error.', 'Which would feel more frustrating?', 'Having no real structure to follow.', 'Having no room to experiment in your own way.'),
  (6, 'Personal Achievement', 'Belonging', 'Recognition', 'You achieve a personal goal you''ve been working on for a long time.', 'You tell a few close people who you know will truly understand what it means to you.', 'You share it more broadly because you want everyone to celebrate with you.', 'Which would feel more frustrating?', 'People not realizing the personal significance of the achievement.', 'People not knowing about the achievement at all.'),
  (7, 'Group Disagreement', 'Belonging', 'Recognition', 'You are with a group of friends who are all agreeing with an opinion you don''t share.', 'You stay quiet — you don''t need to ruffle feathers.', 'You share your perspective and let the conversation unfold.', 'Which would feel lonelier?', 'Being the only one in the room who disagrees.', 'Having your opinion go unheard.'),
  (8, 'Getting Dressed', 'Belonging', 'Recognition', 'You''re getting dressed to go out to a social gathering.', 'You wear your comfy clothes even if you might stand out.', 'You dress to be noticed.', 'Which would feel more uncomfortable?', 'Wearing something that doesn''t feel like you.', 'Being over- or under-dressed for the gathering.'),
  (9, 'Choosing a Gift', 'Belonging', 'Recognition', 'You are choosing a gift for a close friend.', 'You pick something that shows you deeply understand their personality.', 'You pick something impressive that you know they will value highly.', 'Which would feel worse?', 'They don''t think the gift fits them.', 'They don''t seem impressed by the effort you put in.'),
  (10, 'Telling a Story', 'Connections', 'Recognition', 'You are telling a story to a group of people.', 'You love when the group chimes in and adds to the energy.', 'You prefer having the floor so you can tell the story your way.', 'Which would feel more rewarding?', 'Feeling like the story created a buzz in the room.', 'Feeling like you really nailed the delivery.'),
  (11, 'Post-Dinner Dishes', 'Purpose', 'Ecosystem', 'You finished cooking a big meal and the kitchen is a mess.', 'You power through and do the dishes right away.', 'You leave it for tomorrow and go relax for the evening.', 'Which would cause you more distress?', 'The mental weight of a task left unfinished.', 'The exhaustion of forcing yourself to move when your battery is empty.'),
  (12, 'Funny Video', 'Connections', 'Ecosystem', 'You stumble upon a hilarious video clip.', 'You immediately send it to a friend to see their reaction.', 'You save it to watch again later.', 'Which would be more of a letdown?', 'Sending it to a friend and not getting a response.', 'Going back to watch it later and realizing you never saved it.'),
  (13, 'Home Office Setup', 'Purpose', 'Belonging', 'You are setting up your new home office.', 'You arrange everything in its place so you know where to find things.', 'You go with your gut and make the space feel like home.', 'Which would feel more distracting?', 'An office that has a great vibe but is totally disorganized.', 'An office that is productive but feels cold.'),
  (14, 'Friend''s Dilemma', 'Purpose', 'Ecosystem', 'A friend asks for your take on a difficult situation they''re in.', 'You give them the hard truth even if it''s uncomfortable.', 'You offer your care and support but shy away from anything too controversial.', 'What would feel harder to bear?', 'Being too soft and not helping them fix the issue.', 'Being too blunt and hurting their feelings.'),
  (15, 'Friends Out of Town', 'Connections', 'Ecosystem', 'Your friends are all out of town for the weekend.', 'You feel dim and sluggish because there is no one to hang out with.', 'You feel centered and restored by the time to yourself.', 'Which would feel more frustrating?', 'Not having anyone to grab dinner with when you''re feeling social.', 'A friend breaking through "do not disturb" to text you while you''re unwinding.'),
  (16, 'Typo in a Text', 'Belonging', 'Purpose', 'You realize you made a small typo in a text you just sent.', 'You edit the text to make sure your message is correct.', 'You ignore it because the person will get the gist anyway.', 'Which would feel more frustrating?', 'Sending a message that doesn''t truly reflect what you meant.', 'Wasting time and energy on a minor detail that is already good enough.'),
  (17, 'Party Winding Down', 'Connections', 'Ecosystem', 'You are at a party and the energy is starting to wind down.', 'You try to keep the spark alive by suggesting one more activity.', 'You take that as your cue to head home and recharge.', 'Which would feel more frustrating?', 'Leaving early and missing out.', 'Staying too long and feeling drained the next day.'),
  (18, 'Getting Moving', 'Connections', 'Purpose', 'You want to get in some movement to get your heart pumping.', 'You join a high-energy group class where everyone is feeding off the music.', 'You put your earbuds in and take a solo jog through your favorite park.', 'Which would feel more difficult?', 'Finding motivation when you don''t have others around to push you.', 'Feeling distracted by other people''s pace when you are trying to hit your own goal.'),
  (19, 'Bookstore', 'Purpose', 'Agency', 'You are browsing a bookstore.', 'You go straight to the section you''re interested in to find a specific title.', 'You wander the aisles to see what happens to catch your eye.', 'Which would feel more frustrating?', 'Leaving empty-handed because the specific book you wanted was out of stock.', 'Being told exactly which book you should buy instead of finding one yourself.'),
  (20, 'Restaurant Order', 'Purpose', 'Agency', 'You are looking at a menu at a new restaurant.', 'You order the house specialty because you want the best possible meal.', 'You order the most unique thing on the menu because you want to try something new.', 'What would be a bigger disappointment?', 'A mediocre meal when you could have ordered the most popular dish.', 'Being predictable and ordering exactly what everyone else orders.'),
  (21, 'Messy Room at Night', 'Stability', 'Ecosystem', 'You''re getting ready to relax for the evening and notice your room is a mess.', 'You tidy things up before you can really relax.', 'You light a candle, put on some music, and kick your feet up.', 'Which would feel harder to tolerate?', 'Spending time in a cluttered space when you''re trying to relax.', 'Forcing yourself to clean when you just need to breathe.'),
  (22, 'Community Project', 'Purpose', 'Connections', 'You are participating in a local community project.', 'You want to be assigned the task that is most critical to the project''s success.', 'You want to be assigned the task where you get to interact with the most people.', 'Which would feel harder to tolerate?', 'Your contribution was fun but didn''t actually move the needle on the goal.', 'You completed a major task but did it in total isolation from the group.'),
  (23, 'Neighbor Disagreement', 'Belonging', 'Ecosystem', 'You have a small disagreement with a neighbor.', 'You send a text to clarify your position immediately.', 'You wait for a few days to let the tension fade on its own.', 'Which would feel harder to handle?', 'Feeling misunderstood.', 'Feeling unspoken tension.'),
  (24, 'Last-Minute Road Trip', 'Connections', 'Stability', 'You are invited to a last-minute road trip.', 'You say yes because you love the momentum of a spontaneous idea.', 'You say no because you already have your weekend routine set.', 'Which would cause more regret?', 'Sticking to your plan and missing out on a group memory.', 'Scrapping your plan and finding the trip was a letdown.'),
  (25, 'New Dish', 'Stability', 'Agency', 'You are learning to cook a complex new dish.', 'You stick to the recipe exactly to ensure it tastes right.', 'You swap ingredients and experiment with the flavors as you go.', 'Which would feel like a bigger failure?', 'A dish that tastes bad because you took a risk.', 'A dish that anyone could have made.'),
  (26, 'Movie Night', 'Belonging', 'Recognition', 'You are watching a movie with a group of friends.', 'You suggest a movie that everyone has heard of and will likely enjoy.', 'You suggest something obscure that could expand everyone else''s taste.', 'Which would feel more disappointing?', 'Suggesting a movie that no one ended up liking.', 'Not speaking up and watching the same old movie again.'),
  (27, 'Birthday Cash', 'Purpose', 'Agency', 'You get some cash from a family member for your birthday.', 'You buy something practical that you''ve been needing for a while.', 'You spend it on a spontaneous experience like a concert or a nice dinner.', 'Which would feel harder to tolerate?', 'Spending money on a "want" when a serious "need" is still unaddressed.', 'Being sensible and missing out on a story you could have told later.'),
  (28, 'Neighborhood Walk', 'Stability', 'Agency', 'You''re taking a walk in your neighborhood.', 'You take the exact same route you always take because it''s familiar.', 'You turn down a street you''ve never been on just to see where it goes.', 'Which would feel more frustrating?', 'Getting lost while exploring.', 'A predictable routine with nothing new to discover.'),
  (29, 'Wedding Reception', 'Ecosystem', 'Connections', 'You are at a wedding reception where you don''t know many people.', 'You grab some appetizers and sign the guestbook.', 'You head to the dance floor to find the center of the energy.', 'Which would feel harder to tolerate?', 'Forcing yourself to be "on" when you''d rather just observe.', 'Being left out of the fun while everyone else is dancing.'),
  (30, 'Hobby Afternoon', 'Purpose', 'Connections', 'You have a free afternoon to spend on your favorite hobby.', 'You go solo so you can stay in the zone and finish exactly what you planned.', 'You head to a group meetup where the focus is more on the social buzz than the output.', 'Which would feel harder to tolerate?', 'Having your productivity slowed down because you had to stop and chat with others.', 'Hitting a major milestone but having no one there to high-five or share the moment with.'),
  (31, 'End of Day Phone', 'Stability', 'Connections', 'You are looking at your phone at the end of a long day.', 'You clear out all your notifications and organize your apps.', 'You scroll through social media or a news feed to see what''s happening in the world.', 'Which would feel harder to tolerate?', 'The mental clutter of unread notifications lingering on your screen.', 'The feeling of being stuck in your own bubble while the rest of the world is moving without you.'),
  (32, 'Last-Minute Getaway', 'Stability', 'Agency', 'You''re planning a last-minute weekend getaway.', 'You go back to a favorite spot where you''re a regular.', 'You pick a place you''ve never been and try something new.', 'Which would feel more frustrating?', 'Wasting a weekend on a new place that didn''t live up to the hype.', 'Coming back from a predictable weekend where you didn''t have new experiences.'),
  (33, 'Helping Friend Move', 'Purpose', 'Connections', 'You''re helping a friend move into a new apartment.', 'You take charge of the logistics to make sure the truck is packed efficiently.', 'You put together a playlist and grab some snacks to make the day more fun.', 'Which would feel harder to tolerate?', 'Taking twice as long to move because there was no plan.', 'A long, productive day that felt like a chore instead of a shared experience.'),
  (34, 'Moving Book', 'Recognition', 'Ecosystem', 'You just finished reading a book that moved you deeply.', 'You tell others about it so they can find it too.', 'You keep the feeling to yourself and sit with the impact it had on you.', 'Which would feel harder to tolerate?', 'Knowing you had a great recommendation but failed to share it with anyone.', 'Feeling pressured to explain a feeling that you''d rather keep private.'),
  (35, 'Trivia Leader', 'Purpose', 'Belonging', 'You are asked to lead a small group in a trivia game.', 'You focus on getting the right answers to win the game.', 'You focus on making sure everyone in the group gets a chance to participate.', 'Which would feel more frustrating?', 'Losing the game because the group spent too much time debating bad guesses.', 'Winning the game but realizing half the team felt ignored or left out.'),
  (36, 'Concert Seating', 'Agency', 'Connections', 'You are choosing a seat for a concert in a big arena.', 'You pick a seat on the aisle so you can leave quickly and avoid the rush.', 'You pick a seat up front and center to feel the shared energy.', 'Which would feel harder to tolerate?', 'Being stuck in a crowd with no easy way to leave on your own terms.', 'Watching the show from the sidelines and feeling disconnected from the crowd''s excitement.'),
  (37, 'Family Gathering', 'Purpose', 'Recognition', 'You are at a family gathering.', 'You take on the role of the helper, making sure food is served and things are running smoothly.', 'You take on the role of the storyteller, keeping everyone entertained and laughing.', 'Which would feel more frustrating?', 'Feeling like you didn''t contribute anything useful to the event.', 'Feeling like your presence didn''t stand out to anyone.'),
  (38, 'Fitness Program', 'Stability', 'Agency', 'You are starting a new fitness program.', 'You follow a pre-made plan created by an expert.', 'You listen to your body and decide what to do each day as you go.', 'Which would feel more uncomfortable?', 'Not knowing if your own choices are actually leading to progress.', 'Feeling stuck in a rigid routine that doesn''t let you follow your intuition.'),
  (39, 'Museum Visit', 'Agency', 'Ecosystem', 'You are at a museum.', 'You read every plaque to make sure you understand the history of each piece.', 'You walk through quickly and only stop at the pieces that make you feel something.', 'Which would feel more frustrating?', 'Leaving the museum feeling like you missed out on important knowledge or context.', 'Forcing yourself to read facts and figures when you''ve already lost the emotional connection to the art.'),
  (40, 'Joke at Your Expense', 'Connections', 'Recognition', 'You are in a conversation and someone makes a joke at your expense.', 'You laugh along to keep the group energy high and positive.', 'You make a sharp, snippy comeback to show them what you got.', 'Which would feel more uncomfortable?', 'Being the person who killed the vibe by taking things too seriously.', 'Being the person who looked weak by not standing up for yourself.'),
  (41, 'Birthday Dinner', 'Agency', 'Belonging', 'You are planning a dinner for your birthday.', 'You choose your absolute favorite restaurant, even if it''s out of the way for others.', 'You choose a place that is easy for everyone to get to and has something for everyone.', 'Which would feel more uncomfortable?', 'Spending your birthday at a reliable restaurant that you don''t actually care for.', 'The guilt of knowing your guests are inconvenienced just for you.'),
  (42, 'Found $20', 'Stability', 'Agency', 'You find a $20 bill on the sidewalk.', 'You put it in your wallet and save it for a rainy day.', 'You immediately use it to buy a treat for yourself or a friend.', 'Which would feel more frustrating?', 'Realizing later you''re short on cash for a necessity because you blew that $20 on a whim.', 'Looking at that same $20 in your wallet days later and feeling like you sucked the fun out of a lucky moment.'),
  (43, 'Phone Wallpaper', 'Stability', 'Ecosystem', 'You are choosing a new wallpaper for your phone.', 'You pick a clean, minimal design that makes your apps easy to see.', 'You pick a photo of a place or person that makes you feel happy.', 'Which would feel more frustrating?', 'Having a beautiful background that makes your screen feel cluttered and hard to navigate.', 'Having a perfectly organized phone that feels cold and lacks any personal connection.'),
  (44, 'Outfit Twin', 'Connections', 'Recognition', 'You are at a party and you realize you are wearing the exact same outfit as someone else.', 'You introduce yourself and go around showing everyone your matching outfits.', 'You avoid them, feeling a bit annoyed that your unique look has been compromised.', 'Which would feel more annoying?', 'Seeing your "outfit twin" actively avoid you all night because they''re taking it too seriously.', 'Having to hear everyone crack jokes about your "twin outfits" for the rest of the night.'),
  (45, 'Friend Running Late', 'Purpose', 'Ecosystem', 'You are waiting for a friend who is running 15 minutes late.', 'You use the time to catch up on texts or emails.', 'You people-watch and enjoy the break in the day.', 'Which would feel more frustrating?', 'Feeling like you''ve wasted 15 minutes of your life doing absolutely nothing productive.', 'Feeling like you''ve ruined a rare moment of peace by jumping right back into your to-do list.'),
  (46, 'New Clothing', 'Purpose', 'Recognition', 'You are buying a new piece of clothing.', 'You grab something high-quality that will last for years.', 'You look for something unique that will turn heads.', 'Which would feel more frustrating?', 'Spending money on something trendy that will be out of style by next season.', 'Buying something sensible that makes you feel completely invisible in a crowd.'),
  (47, 'Overwhelmed in a Crowd', 'Ecosystem', 'Agency', 'You''re in a high-energy group setting and feel a bit overwhelmed.', 'You find a quiet corner to observe the energy from a distance.', 'You leave the room entirely to find a place where you can be alone.', 'Which would feel more uncomfortable?', 'Feeling trapped in the room and unable to fully reset because you''re still witnessing the chaos.', 'Feeling completely cut off and missing the pulse of what''s happening because you''ve left the space.'),
  (48, 'Sharing a Mistake', 'Purpose', 'Connections', 'You are telling a story about a mistake you made.', 'You tell it in a way that highlights the lesson you learned.', 'You tell it in a way that makes it the funniest story in the room.', 'Which would feel more frustrating?', 'Realizing people are laughing at the story but totally missing the point of why it happened.', 'Realizing you''ve turned a great story into a lecture and sucked all the air out of the room.'),
  (49, 'Road Trip Playlist', 'Belonging', 'Agency', 'You are choosing a playlist for a road trip.', 'You pick a list of classic hits that you know everyone will want to sing along to.', 'You pick a list of new, underground music you''ve been wanting to hear.', 'Which would feel more draining?', 'The awkwardness of a silent car because no one else knows or likes the music you picked.', 'Having to listen to overplayed songs all day just to keep the peace in the car.'),
  (50, 'Friend''s Suggestion', 'Purpose', 'Belonging', 'You are working on a project and a friend offers a suggestion that you don''t think is very good.', 'You explain why their idea doesn''t work and stick to your original plan.', 'You find a way to incorporate a small part of their idea just to make them feel included.', 'Which would feel more frustrating?', 'Knowing you compromised the quality of the final result just to spare someone''s feelings.', 'Knowing you made your friend feel shot down just to get the project right.')
on conflict (id) do update set
  topic = excluded.topic,
  cluster_a = excluded.cluster_a,
  cluster_b = excluded.cluster_b,
  standard_question = excluded.standard_question,
  standard_option_a = excluded.standard_option_a,
  standard_option_b = excluded.standard_option_b,
  sharpened_question = excluded.sharpened_question,
  sharpened_option_a = excluded.sharpened_option_a,
  sharpened_option_b = excluded.sharpened_option_b;

